def parse_trade(self, trade, market=None):
    timestamp = None
    if 'Timestamp' in trade:
        timestamp = trade['Timestamp'] * 1000
    elif 'TimeStamp' in trade:
        timestamp = self.parse8601(trade['TimeStamp'])
    price = None
    cost = None
    if 'Price' in trade:
        price = trade['Price']
    elif 'Rate' in trade:
        price = trade['Rate']
    fee = None
    if 'Fee' in trade:
        fee = trade['Fee']
    elif 'TransactionFee' in trade:
        fee = trade['TransactionFee']
    return {
        'id': None,
        'info': trade,
        'timestamp': timestamp,
        'datetime': self.iso8601(timestamp),
        'symbol': market['symbol'],
        'type': None,
        'side': trade['Type'].lower(),
        'price': price,
        'cost': cost,
        'amount': trade['Amount'],
        'fee': fee,
    }
